const { publicStores } = require('./stores');
const { haversineKm, toLngLat } = require('./geo');
const { paginate } = require('./paginate');

const routes = {
  'GET /stores': (req) => ({ status: 200, body: paginate(publicStores(), req.query) }),
  'GET /stores/:id/distance': (req) => {
    const store = publicStores().find((s) => s.id === req.params.id);
    return { status: 200, body: { km: haversineKm(toLngLat(req.query.lat, req.query.lng), store.location) } };
  },
};

module.exports = { routes };
